import type { Metadata } from "next";
import Link from "next/link";
import { notFound } from "next/navigation";
import { Section } from "@/components/marketing/primitives";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { GAME_ART_SLUG, GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { listCatalogFamilies, listCategoryCounts, queryCatalogMods, totalDownloadsFor, formatDownloads } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

/**
 * A real per-game NxLabs landing page — item 7 of the NxLabs brief. Only
 * rendered for families that actually have catalogued mods (real
 * listCatalogFamilies() rows), never a placeholder page for a game with
 * nothing in it.
 */
export async function generateStaticParams(): Promise<Array<{ family: string }>> {
  const families = await listCatalogFamilies();
  return families.map((f) => ({ family: f.family }));
}

export async function generateMetadata({ params }: { params: Promise<{ family: string }> }): Promise<Metadata> {
  const { family } = await params;
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
  return {
    title: `${label} Mods & Plugins — NxLabs`,
    description: `Browse verified ${label} mods and plugins with real download counts, licenses, and version support — download free, or add straight to your Nxeon server.`,
    alternates: { canonical: `/mods/games/${family}` },
  };
}

type Search = { q?: string; sort?: string; category?: string; page?: string };

export default async function GameModsMarketingPage({
  params,
  searchParams,
}: {
  params: Promise<{ family: string }>;
  searchParams: Promise<Search>;
}) {
  const { family } = await params;
  const families = await listCatalogFamilies();
  const entry = families.find((f) => f.family === family);
  if (!entry) notFound();

  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const category = sp.category?.trim() || undefined;
  const page = Number(sp.page) || 1;

  const [categoryCounts, result, totalDownloads] = await Promise.all([
    listCategoryCounts(family),
    queryCatalogMods({ family, category, q, sort, page }),
    totalDownloadsFor(family),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? entry.label;
  const heroSlug = GAME_ART_SLUG[family as GameFamily]?.hero;

  // Real, DB-wide category counts (listCategoryCounts' own groupBy) — not
  // derived from `mods`, which is only the current page.
  const chips = categoryCounts.map((c) => ({ key: c.category, label: c.category, count: c.count }));

  return (
    <>
      <section className="relative overflow-hidden">
        {heroSlug && (
          <div className="absolute inset-0 -z-10">
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={`/games/art/${heroSlug}_hero.jpg`} alt="" className="h-full w-full object-cover opacity-30" />
            <div className="absolute inset-0 bg-gradient-to-t from-[var(--bg)] via-[var(--bg)]/70 to-transparent" />
          </div>
        )}
        <div className="rail py-20 sm:py-28">
          <p className="text-xs font-semibold uppercase tracking-widest text-brand-300">
            <Link href="/mods" className="hover:underline">
              NxLabs
            </Link>{" "}
            / {label}
          </p>
          <h1 className="mt-3 text-4xl font-bold tracking-tight text-[var(--fg)] sm:text-5xl">{label} mods &amp; plugins</h1>
          <p className="mt-4 max-w-2xl text-lg text-[var(--fg-muted)]">
            {entry.count} verified add-ons for {label} — real download counts, real licenses, and a direct link to the
            source. Free for anyone, one click if you have a matching Nxeon server.
          </p>
          <div className="mt-6 flex flex-wrap gap-6 text-sm text-[var(--fg-muted)]">
            <span>
              <strong className="text-[var(--fg)]">{entry.count}</strong> mods &amp; plugins
            </span>
            {totalDownloads > 0 && (
              <span>
                <strong className="text-[var(--fg)]">{formatDownloads(totalDownloads)}</strong> total downloads
              </span>
            )}
          </div>
          <div className="mt-6 flex gap-3">
            <a href="#browse" className="btn-primary">
              Browse {label} mods
            </a>
            <Link href={`/${family}-server-hosting`} className="btn-secondary">
              See {label} hosting plans
            </Link>
          </div>
        </div>
      </section>

      <Section>
        <div id="browse">
          <StoreBrowser
            mods={mods}
            total={total}
            page={resolvedPage}
            totalPages={totalPages}
            perPage={perPage}
            chips={chips}
            chipField="category"
            activeChipKey={category}
            basePath="/mods"
            browsePath={`/mods/games/${family}`}
            q={q}
            sort={sort}
            searchPlaceholder={`Search ${label} mods…`}
          />
        </div>
      </Section>
    </>
  );
}

import type { Metadata } from "next";
import Link from "next/link";
import { PageHero, Section, SectionTitle } from "@/components/marketing/primitives";
import { StoreBrowser, type SortKey } from "@/components/mods/StoreBrowser";
import { PopularGamesStrip } from "@/components/mods/PopularGamesStrip";
import { FaqJsonLd } from "@/components/marketing/StructuredData";
import { listCatalogFamilies, queryCatalogMods, totalDownloadsFor, formatDownloads } from "@/lib/mods-catalog";

export const dynamic = "force-dynamic";

const VALID_SORTS = new Set<SortKey>(["featured", "downloads", "latest", "rating"]);
function parseSort(v?: string): SortKey {
  return v && VALID_SORTS.has(v as SortKey) ? (v as SortKey) : "featured";
}

export const metadata: Metadata = {
  title: "NxLabs — Free Mods, Plugins & Server Add-ons",
  description:
    "NxLabs is Nxeon's free, public mod & plugin catalog — verified against Modrinth, SpigotMC, and Thunderstore. Browse and download with no account required.",
  alternates: { canonical: "/mods" },
  openGraph: { title: "NxLabs — Free Mods, Plugins & Server Add-ons", type: "website" },
};

const FAQ = [
  {
    q: "Do I need an Nxeon account to download from NxLabs?",
    a: "No. Every mod page links to its real, authoritative source (Modrinth, SpigotMC, or Thunderstore) — anyone can download for free with no account.",
  },
  {
    q: "What does \"Verified\" mean on a mod?",
    a: "Verified mods have been checked live against their source's own API — real download counts, supported game versions, and file size, refreshed periodically so a removed or deprecated project stops being listed.",
  },
  {
    q: "Can I install a mod straight onto my server?",
    a: "If you have an Nxeon game server matching the mod's game, log in and use \"Add to my server\" for a one-click install. Anyone else gets the same direct download link.",
  },
];

type Search = { q?: string; sort?: string; page?: string };

export default async function ModsCatalogPage({ searchParams }: { searchParams: Promise<Search> }) {
  const sp = await searchParams;
  const q = (sp.q ?? "").trim();
  const sort = parseSort(sp.sort);
  const page = Number(sp.page) || 1;

  const [families, result, totalDownloads] = await Promise.all([
    listCatalogFamilies(),
    queryCatalogMods({ q, sort, page }),
    totalDownloadsFor(),
  ]);
  const { mods, total, totalPages, perPage, page: resolvedPage } = result;
  const totalMods = families.reduce((sum, f) => sum + f.count, 0);

  // Family chips point at the real dedicated /mods/games/[family] pages
  // (already correctly paginated) rather than re-filtering this page's own
  // array in place — the counts here are real DB-wide totals
  // (listCatalogFamilies' own groupBy), and at 32k+ mods in one family a
  // client-side re-filter of just this page's ~24 loaded rows could show
  // "0 results" for a chip advertising thousands.
  const chips = families.map((f) => ({ key: f.family, label: f.label, count: f.count, href: `/mods/games/${f.family}` }));

  return (
    <>
      <FaqJsonLd items={FAQ} />
      <PageHero
        logo={
          // eslint-disable-next-line @next/next/no-img-element
          <img src="/nxlabs/logo.png" alt="NxLabs" className="h-10 w-auto" />
        }
        eyebrow="Mods fuel better games"
        title="Customize without"
        highlight="limits"
        sub="Discover, download, and share verified mods, plugins, and add-ons for your favorite Nxeon-hosted games — real download counts, real licenses, always a direct link to the source."
        primary={{ label: "Browse mods", href: "#browse" }}
        secondary={{ label: "Explore games", href: "#games" }}
        visual={
          // eslint-disable-next-line @next/next/no-img-element
          <img
            src="/nxlabs/hero-collage.png"
            alt="Mods across Minecraft, Rust, Valheim, CS2 and Palworld"
            className="w-full rounded-2xl border border-white/10 object-cover"
          />
        }
      />

      <Section>
        <div className="mx-auto grid max-w-4xl grid-cols-3 gap-4 text-center">
          <Stat value={totalMods.toLocaleString()} label="Mods & plugins" />
          <Stat value={String(families.length)} label="Games supported" />
          <Stat value={formatDownloads(totalDownloads) ?? "0"} label="Total downloads" />
        </div>
      </Section>

      <Section>
        <div id="games">
          <SectionTitle eyebrow="Browse by game" title="Popular games" />
          <div className="mt-6">
            <PopularGamesStrip families={families} hrefFor={(family) => `/mods/games/${family}`} />
          </div>
        </div>
      </Section>

      <Section>
        <div id="browse">
          <SectionTitle eyebrow="The full catalog" title="Featured mods" />
          <div className="mt-6">
            <StoreBrowser
              mods={mods}
              total={total}
              page={resolvedPage}
              totalPages={totalPages}
              perPage={perPage}
              chips={chips}
              chipField="gameFamily"
              basePath="/mods"
              q={q}
              sort={sort}
              showGameBadge
            />

